"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["42837"],{60256(e){e.exports=JSON.parse('{"id":"V4-014","slug":"renters-insurance","term":"Renters Insurance","also_known_as":[],"difficulty":"Beginner","definition":"Renters insurance is insurance for people who rent their home, covering their personal belongings against risks such as theft, fire and water damage, and usually including personal liability cover.","explanation":["When someone rents a home, the landlord\u2019s insurance typically covers the building itself but not the tenant\u2019s possessions. Renters insurance fills this gap.","A typical policy covers belongings such as furniture, clothing, electronics and jewellery up to a set limit, often with lower limits for valuable items unless listed separately. Many policies also include personal liability cover, which pays if the tenant accidentally injures someone or damages someone else\u2019s property, and additional living expenses if the home becomes uninhabitable after an insured event.","For example, if a fire in a rented flat destroys a tenant\u2019s belongings, renters insurance could pay to replace them and cover the cost of a hotel while the flat is repaired.","Renters insurance is generally inexpensive compared with homeowners insurance, because it does not cover the building. Some landlords require tenants to have it. The term is mainly used in the United States; in the United Kingdom and some other countries, the equivalent is usually called contents insurance."],"note":"","total":1725,"prev":{"slug":"rental-yield","term":"Rental Yield"},"next":{"slug":"replacement-cost","term":"Replacement Cost"}}')}}]);